INSERT INTO public.corpus_findings (area, topic, claim, basis, confidence, sport, quantities) VALUES
  ('periodization', 'taxonomy', 'Three distinct progression models exist for strength lifts — accumulation, intensification, and realization — each defined by a specific pattern of how sets, load, and reps change week to week, not just labels.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'duration', 'A mesocycle runs 3-5 overload weeks plus 1 deload week; the worked example uses a 4:1 overload-to-deload ratio for a 5-week mesocycle, deload placed first.', 'experience', 'strong', NULL, '{"overload_weeks":"3-5","deload_weeks":1,"example_ratio":"4:1","example_total_weeks":5}'::jsonb),
  ('periodization', 'markers', 'Accumulation progression: weekly sets rise (2 in deload week, then 5, 6, 7, 8) while load stays fixed in a 6-10 rep range, targeting structural/hypertrophy adaptation.', 'experience', 'strong', NULL, '{"sets_by_week":[2,5,6,7,8],"rep_range":"6-10"}'::jsonb),
  ('periodization', 'markers', 'Intensification progression: set count stays flat (2 in deload, 3 thereafter) while load increases roughly 5kg per week in a 3-6 rep range, targeting neural/strength-specific adaptation.', 'experience', 'strong', NULL, '{"sets":"2 deload / 3 thereafter","load_increase_per_week_kg":5,"rep_range":"3-6"}'::jsonb),
  ('periodization', 'markers', 'Realization progression: sets fall each week (3 down to 1 by the final week) while reps drop and load rises correspondingly, aiming to shed fatigue while peaking performance.', 'experience', 'strong', NULL, '{"sets_by_week":"3 to 1"}'::jsonb),
  ('periodization', 'transitions', 'Across the accumulation-intensification-realization sequence, exercise selection shifts toward greater specificity — from stiff-leg deadlifts, to snatch/clean-grip deadlifts, to classic snatch/clean pulls closest to the competition lift.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'markers', 'Competition (skill) lifts aren''t progressively overloaded across the mesocycle; instead they''re autoregulated daily by intensity band — light days ~60%, a moderate day 70-90%, one heavy day 90%+.', 'experience', 'strong', NULL, '{"light_pct":60,"moderate_pct":"70-90","heavy_pct":"90+"}'::jsonb),
  ('periodization', 'markers', 'Accessory exercise progression uses an autoregulated RIR approach in a 6-15 rep range: reps in reserve are set to decrease week to week, letting reps rise naturally toward failure.', 'experience', 'strong', NULL, '{"rep_range":"6-15"}'::jsonb),
  ('periodization', 'taxonomy', 'Periodization is framed as long-term, goal-directed planning across meso/macrocycles, distinct from programming — the day-to-day/session tactics used within a mesocycle of roughly up to about 4 weeks.', 'experience', 'moderate', NULL, '{"mesocycle_weeks":"up to ~4"}'::jsonb),
  ('periodization', 'transitions', 'Powerlifter periodization shifts from high-volume/low-intensity assistance work early to lower-volume, higher-intensity, lift-specific work near the meet; bodybuilders traditionally skip this, repeating one split 4-12 weeks before switching.', 'experience', 'moderate', NULL, '{"switch_interval_weeks":"4-12"}'::jsonb),
  ('periodization', 'models', 'Cites a meta-analysis finding no meaningful difference between periodization styles for hypertrophy outcomes, suggesting periodization may matter more for performance-specific goals than for general muscle growth.', 'cited_study', 'moderate', NULL, NULL),
  ('periodization', 'models', 'Linear periodization is defined as starting at higher volume/lower intensity and progressively shifting to lower volume/higher intensity as the cycle proceeds.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'models', 'Block periodization is defined as sequential dedicated blocks — a volume block, then an intensity block, then a taper — rather than continuous blending of variables.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'models', 'Undulating periodization varies rep target by day within a week (example: 8/6/4 reps early in a cycle, shifting to 5/3/1 near competition), and can combine with linear progression.', 'experience', 'strong', NULL, '{"reps_early":"8/6/4","reps_late":"5/3/1"}'::jsonb),
  ('periodization', 'models', 'Cites a Stronger-by-Science-referenced meta-analysis finding undulating periodization modestly outperforms both non-periodized and linear-periodized training for strength, with the advantage most notable in trained lifters.', 'cited_study', 'moderate', NULL, NULL),
  ('periodization', 'models', 'Cites a study comparing the Hatfield method (heavy/moderate/light zones combined in one session, progressed only by adding load/reps — technically non-periodized) to a periodized weekly-undulating plan, finding no hypertrophy difference.', 'cited_study', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'Weekly RIR target drops roughly by 1 across a mesocycle, starting around 3-4 reps in reserve in week 1 and reaching 0-1 RIR by the final week; RIR should never increase.', 'experience', 'strong', NULL, '{"start_rir":"3-4","end_rir":"0-1","weekly_step":1}'::jsonb),
  ('periodization', 'markers', 'To hit each week''s harder RIR target, lifters add either load (default) or reps when load jumps are too coarse (e.g. dumbbells), switching back to load once reps exceed the rep-range ceiling.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'markers', 'Weekly set (volume) progression uses a two-factor check: soreness timing (healed early vs. just-in-time vs. still sore) cross-checked against performance (over/on/under target), setting whether to add 2, 1, or 0 sets.', 'experience', 'strong', NULL, '{"sets_add":"0-2"}'::jsonb),
  ('periodization', 'deload', 'Distinct performance decline across two consecutive sessions for a muscle group signals it has hit maximum recoverable volume; response is to cut that muscle group''s volume by half or take a recovery week.', 'experience', 'strong', NULL, '{"volume_cut_pct":50}'::jsonb),
  ('periodization', 'deload', 'Deload timing is autoregulated rather than fixed: triggered once most trained muscle groups sit at 0-1 RIR with broadly declining performance for about two weeks, signaling proximity to maximum recoverable volume.', 'experience', 'strong', NULL, '{"trigger_weeks":"~2"}'::jsonb),
  ('periodization', 'duration', 'Mesocycle length is treated as flexible — commonly around 4 weeks but extendable toward 8 — with longer mesocycles holding RIR flat some weeks instead of dropping it every week.', 'experience', 'moderate', NULL, '{"mesocycle_weeks":"4-8"}'::jsonb),
  ('periodization', 'markers', 'When a lifter has to work harder than expected to hit the target RIR without technically underperforming, the rule is to withhold added volume regardless of soreness, letting recovery catch up first.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'Rationale for progressively lowering reps-in-reserve across a mesocycle: proximity to failure drives more growth, but cumulative fatigue rises in step, so the model deliberately trades the two off until deload is forced.', 'mechanistic', 'moderate', NULL, NULL),
  ('periodization', 'duration', 'Standard cycle-length convention given: microcycle is about a week, mesocycle is about 3 weeks up to 2 months (commonly a month or two), macrocycle is multiple mesocycles culminating in a target point.', 'experience', 'moderate', NULL, '{"microcycle_weeks":1,"mesocycle_weeks":"3-8"}'::jsonb),
  ('periodization', 'taxonomy', 'Field consensus lands on periodization as planned variation meant to peak a specific outcome at a specific time via organized phases across at least two mesocycles; one cycle alone doesn''t count.', 'experience', 'moderate', NULL, '{"min_mesocycles_for_macrocycle":2}'::jsonb),
  ('periodization', 'taxonomy', 'Hypertrophy, unlike strength, has no single natural peak time point, so under the strict peak-a-specific-outcome-at-a-specific-time definition, periodization may not strictly apply to hypertrophy goals at all.', 'mechanistic', 'hedged', NULL, NULL),
  ('periodization', 'transitions', 'When lifters return to a specific exercise after weeks away, they often immediately set a new PR; this is read as evidence that hypertrophy from the break, not motor-skill practice, carries over.', 'experience', 'hedged', NULL, NULL),
  ('periodization', 'models', 'All periodization models formally studied (linear, reverse-linear, block, daily-undulating, weekly-undulating) were designed and tested to peak strength, not hypertrophy, so equal hypertrophy outcomes across them don''t prove periodization is useless for it.', 'cited_study', 'moderate', NULL, NULL),
  ('periodization', 'models', 'Roughly four to five studies comparing a rigid single-rep-range hypertrophy prescription against varied approaches (block alternation, undulating ranges, in-session rep pyramids) found a slight hypertrophy edge for variation, tied to non-mechanical factors.', 'cited_study', 'hedged', NULL, '{"study_count":"4-5"}'::jsonb),
  ('periodization', 'transitions', 'Sequencing a multi-mesocycle, strength-focused macrocycle (example: 3-4 mesocycles) before returning to hypertrophy-focused training is described as a deliberate strategy for lifters judged weak relative to their training age.', 'experience', 'hedged', NULL, '{"strength_phase_mesocycles":"3-4"}'::jsonb),
  ('periodization', 'deload', 'Deloading triggered purely by a generic performance-decline rule is unreliable because genuine treatment-resistant overtraining is rare in resistance training; recovery decisions should target whatever specific system is actually the bottleneck.', 'mechanistic', 'moderate', NULL, NULL),
  ('periodization', 'taxonomy', 'Presenter structures a macrocycle as three sequential block types — volume-accumulation, then flat-volume/rising-intensity, then volume-taper/intensity-peak — matching a classic accumulation-intensification-realization shape without naming it as such.', 'experience', 'moderate', NULL, '{"blocks":3}'::jsonb),
  ('periodization', 'duration', 'Example plan: a 5-week block (4 build weeks + 1 unload week) repeated across a 15-week macrocycle of three such blocks building toward a competitive peak.', 'experience', 'moderate', NULL, '{"block_weeks":5,"macrocycle_weeks":15,"blocks_in_macrocycle":3}'::jsonb),
  ('periodization', 'markers', 'In the accumulation block, volume is planned to climb (e.g. 5 to 8 on the presenter''s own relative scale) while intensity holds flat, then both drop in the final unload week.', 'experience', 'hedged', NULL, '{"volume_range":"5-8","intensity":"flat ~5"}'::jsonb),
  ('periodization', 'markers', 'In the final peaking/taper block, volume is planned to fall steadily (e.g. 6 down to 2) while intensity keeps climbing toward its highest point, easing only slightly in the taper week.', 'experience', 'hedged', NULL, '{"volume_range":"6-2","intensity_peak":"9-10"}'::jsonb),
  ('periodization', 'deload', 'Every block ends with a dedicated unloading week on a fixed schedule (not autoregulated) that cuts volume to dissipate fatigue before the next block''s overload phase begins.', 'experience', 'moderate', NULL, '{"deload_position":"final week of each ~5wk block"}'::jsonb),
  ('periodization', 'markers', 'Presenter argues sets x reps x load volume cannot be validly compared across dissimilar exercise types (sprints, jumps, Olympic lifts, squats, conditioning) because range of motion, neural fatigue, and intensity metrics differ too much.', 'mechanistic', 'strong', NULL, NULL),
  ('periodization', 'transitions', 'Because cross-exercise volume math doesn''t work, presenter plans phases with only a relative 1-10 volume/intensity scale per goal, leaving precise numeric prescriptions to the written program and adjusting via fatigue/performance monitoring rather than pre-set math.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'First week of a hypertrophy mesocycle should target close to minimum effective volume — enough work for a mild pump and light soreness, not more — to avoid seeding fatigue too early.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'New exercises or rep ranges should start a mesocycle around 3-4 reps in reserve — enough stimulus to drive hypertrophy without generating so much fatigue it compromises the rest of the mesocycle.', 'experience', 'moderate', NULL, '{"rir":"3-4"}'::jsonb),
  ('periodization', 'transitions', 'A caloric deficit is best matched to a hypertrophy-focused phase, where volume is already high, while calorie maintenance suits a strength-focused phase for muscle and technique/leverage stability.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'transitions', 'The whole hypertrophy-then-strength training cycle should be treated as one unit; the relative lengths of each phase are planned together rather than independently since gains in one depend on what preceded it.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'duration', 'A single hypertrophy block (example given: 5 weeks) is not enough to judge its own effectiveness; meaningful assessment needs to zoom out across multiple blocks (roughly 12-16 weeks) since gains lag the stimulus.', 'experience', 'moderate', NULL, '{"block_weeks":5,"assessment_window_weeks":"12-16"}'::jsonb),
  ('periodization', 'markers', 'End-of-hypertrophy-phase progress is judged less by 1RM jumps, which often don''t move within one phase, and more by proxies: a ''daily minimum'' load feeling easier and less performance anxiety at that load.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'Within a hypertrophy-focused phase, top sets are deliberately kept short of maximal effort compared to a strength phase, so athletes aren''t primed for a fatigue crash that would blunt subsequent hypertrophy work.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'Exercise selection is deliberately held constant across multiple (not all) blocks specifically so identical load/RPE/rep performance can be compared cycle-to-cycle as a progress marker.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'Proactive programming uses dedicated ''intro weeks'' to ramp workload gradually toward peak volume rather than jumping straight to it, framed explicitly as injury/overtraining prevention.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'Example low-fatigue strength phase caps peak intensity around RPE 6-7 for a triple with back-off work kept below RPE 6, trading single-session performance for predictable week-to-week load progression.', 'experience', 'moderate', NULL, '{"rpe_top":"6-7","rpe_backoff":"<6"}'::jsonb),
  ('periodization', 'taxonomy', 'One guest distinguishes ''programming'' (day-to-day/week-to-week variable changes within a microcycle) from ''periodization'' (planned change over meso/macro timescales), arguing daily undulating ''periodization'' is really programming since its swings are day-scale.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'models', 'Multiple meta-analyses (cited: a 2022 review) find no significant hypertrophy difference between periodized and non-periodized resistance training programs.', 'cited_study', 'strong', NULL, NULL),
  ('periodization', 'models', 'That null result is argued to be an artifact: the underlying trials were designed to periodize strength/power, not hypertrophy, so the meta-analysis can''t actually speak to whether hypertrophy-targeted periodization works.', 'mechanistic', 'moderate', NULL, NULL),
  ('periodization', 'models', 'Two named hypertrophy periodization frameworks differ in mechanism: one (RP) progresses via rising weekly volume borrowed from strength/intensity logic; another (Schoenfeld''s) blocks alternating heavier- and lighter-load phases based on hypertrophy mechanisms.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'transitions', 'For bodybuilders (unlike powerlifters), presenter runs a mesocycle or two of heavier loading then a mesocycle or two of lighter loading, rotating the highest-fatigue compound lifts so they appear only every other mesocycle.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'Cited injury-rate data: bodybuilding injuries run 0.24-1 per 1000 training hours versus 1-5.8 for powerlifting, speculatively linked to powerlifters'' narrower, heavier, more constrained exercise/rep-range selection.', 'cited_study', 'hedged', NULL, '{"bb_injury_rate":"0.24-1/1000h","pl_injury_rate":"1-5.8/1000h"}'::jsonb),
  ('periodization', 'duration', 'Exercise rotation frequency should track individual motor-learning speed, not a fixed schedule: cited research shows novices see measurable hypertrophy from isolation moves by about 6 weeks versus about 12 weeks for compound moves.', 'cited_study', 'moderate', NULL, '{"isolation_weeks":6,"compound_weeks":12}'::jsonb),
  ('periodization', 'deload', 'Deloads can anchor injury-modification plans: reduce load/range-of-motion/exercise selection in the week before a scheduled deload, then progress back out of those modifications the week after, once recovery has occurred.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'deload', 'In this example program, deload is scheduled every 3 overload weeks within a 4-week hypertrophy mesocycle, placed as the lowest-volume first week to allow recovery.', 'experience', 'moderate', NULL, '{"overload_weeks_before_deload":3,"mesocycle_length_weeks":4}'::jsonb),
  ('periodization', 'deload', 'Optimal overload-to-deload ratio is trainee-specific; different lifters should use different deload frequencies rather than a single fixed schedule for everyone.', 'experience', 'hedged', NULL, NULL),
  ('periodization', 'transitions', 'Simplest between-mesocycle progression is holding sets, load, and exercise constant and letting reps rise naturally as the trainee gets stronger, until rep range or a plateau make that unworkable.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'When rep ranges on a fixed load climb too high, load is increased between mesocycles, dropping reps back down before building them up again at the new weight.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'transitions', 'Once a specific exercise plateaus across repeated mesocycles, it is swapped for a different exercise targeting the same muscle group to restore a fresh stimulus.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'When a muscle group stalls across most of its exercises, weekly set volume for that group is raised (about 2 sets/week), but not for every muscle group at once, to avoid exceeding recovery capacity.', 'experience', 'moderate', NULL, '{"volume_increase_sets_per_week":2}'::jsonb),
  ('periodization', 'models', 'Undulating periodization suits training with no specific event to prepare for; linear or step periodization suits an athlete preparing for a defined competition.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'models', 'Periodization''s core purpose is structuring rest and alternating high- and low-intensity sessions to optimize recovery between workouts, not simply varying training load over time.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'Training intensity is proactively lowered during a client''s or athlete''s high-external-stress windows (competitive season, demanding work period), while session frequency and habit are preserved rather than dropped.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'deload', 'A short functional-overreach period of roughly 5-10 days of harder training before a planned break (season start, competition, vacation) is used deliberately, with the break itself serving as recovery.', 'experience', 'hedged', NULL, '{"overreach_days_before_break":"5-10"}'::jsonb),
  ('periodization', 'taxonomy', 'For general-population clients, a known high-stress calendar period is planned as an ''offseason transition'' phase emphasizing mobility and maintenance in short 20-30 minute sessions rather than progressive overload.', 'experience', 'moderate', NULL, '{"session_length_min":"20-30"}'::jsonb),
  ('periodization', 'taxonomy', 'Peaking is defined as optimizing the fitness-fatigue relationship for one single competition day, and it begins at the start of the training cycle, not just at the taper.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'markers', 'Peaking work targets neural drive and technical skill through loads above 90% of 1RM, combined with fewer, less frequent heavy sessions and lower overall volume than hypertrophy training.', 'experience', 'strong', NULL, '{"intensity_threshold_pct_1rm":90}'::jsonb),
  ('periodization', 'markers', 'In the final peak, powerlifters take only about 2-3 sessions/month above 90% 1RM versus about 7/month for weightlifters, since no eccentric loading and lighter absolute weight let weightlifters recover faster.', 'experience', 'moderate', NULL, '{"powerlifting_90pct_sessions_per_month":"2-3","weightlifting_90pct_sessions_per_month":7}'::jsonb),
  ('periodization', 'duration', 'Taper length differs by sport: powerlifters use longer, lower-intensity tapers, while weightlifters use shorter tapers and keep training near competition intensity until just days out.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'transitions', 'For weightlifters, squat volume and intensity built early in the cycle shift to a maintenance role during peaking and are rarely tapered toward a 1RM attempt, since squat and competition-lift peaks don''t coincide.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'transitions', 'Advanced lifters cannot maximize multiple related 1RM lifts (e.g., squat and competition lifts, bench and military press) in the same short window; simultaneous peaks become less likely as training age increases.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'deload', 'Recovery modalities like contrast/temperature therapy are emphasized mainly in deload and restorative weeks; during heavy training and competition, sleep and diet remain the primary recovery levers.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'transitions', 'New exercises, novel overload strategies, or untested supplements should not be introduced in roughly the final 10 days before competition, since unfamiliar stimuli cause disproportionate, unpredictable fatigue.', 'experience', 'strong', NULL, '{"no_new_stimulus_window_days":10}'::jsonb),
  ('periodization', 'transitions', 'Periodizing accessory/isolation lifts (heavy vs. light across the week) is possible but yields only marginal extra progress over periodizing just the compound lifts; that time is better spent elsewhere.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'Accessory-lift progression can be tracked in roughly month-long blocks: hold load and reps steady for a month, raise load while letting volume dip, then rebuild volume at the new load.', 'experience', 'moderate', NULL, '{"progression_block_length_weeks":4}'::jsonb),
  ('periodization', 'deload', 'Trained lifters can cut training volume for about 2-4 weeks without losing muscle or strength if a plan exists to restore it; the real risk is a slow decline stretched over 6-12 weeks.', 'experience', 'moderate', NULL, '{"safe_volume_drop_weeks":"2-4","risky_dwindling_window_weeks":"6-12"}'::jsonb),
  ('periodization', 'models', 'Pure linear periodization is the theoretical ideal but is mathematically unsustainable past a novice''s early gains; extrapolating early linear progress compounds to unrealistic totals within 1-2 years, so trained lifters need resets.', 'mechanistic', 'moderate', NULL, NULL),
  ('periodization', 'taxonomy', 'Presents accumulation, intensification, and realization/peaking as the three real macrocycle-level phases, each carrying a distinct volume/intensity manipulation rather than being interchangeable labels.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'duration', 'A mesocycle is an overload block ending in a deload week; long phases (~12 weeks) get split into 3-4 shorter mesocycles because continuous overload for that long stalls progress.', 'experience', 'moderate', NULL, '{"phase_weeks":12,"mesocycles_per_phase":"3-4"}'::jsonb),
  ('periodization', 'markers', 'Accumulation mesocycles progress volume (added sets) week to week while holding intensity constant; the reverse governs intensification mesocycles (intensity/load rises, volume held constant).', 'mechanistic', 'strong', NULL, NULL),
  ('periodization', 'markers', 'Realization/peaking mesocycles simultaneously raise intensity and cut volume across weeks, aiming for peak intensity with minimal accumulated fatigue at the end of the block.', 'mechanistic', 'strong', NULL, NULL),
  ('periodization', 'deload', 'Deload sits on a fixed calendar position -- the last week of each mesocycle -- with volume dropped below week-1 levels regardless of how the athlete is responding; not autoregulated.', 'experience', 'moderate', NULL, '{"deload_position":"final week of mesocycle"}'::jsonb),
  ('periodization', 'deload', 'A taper is mechanically similar to a deload (both reduce fatigue) but serves a different purpose -- deload exists to enable recovery for the next block, taper exists to produce peak competition performance.', 'mechanistic', 'moderate', NULL, NULL),
  ('periodization', 'transitions', 'The same exercises can be kept across accumulation, intensification, and realization mesocycles for a given athlete -- phase identity is carried entirely by how sets/load/distance move, not by swapping exercises.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'duration', 'Annual plan allocates the three phases (accumulation, intensification, realization) across the year based on target competition dates, so phase placement and duration vary by when peak performance is needed.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'Progression within a mesocycle follows an RIR trajectory: sessions start near RIR 3-4 and decline toward RIR 0-1 by the final week; RIR should only hold steady or fall, never rise.', 'mechanistic', 'strong', NULL, '{"start_rir":"3-4","end_rir":"0-1"}'::jsonb),
  ('periodization', 'duration', 'Example accumulation block length is framed as roughly 7-8 weeks, moving through RIR targets in 2-week increments (RIR3 for 2 weeks, RIR2, RIR1, then RIR0 for a final week) before deload.', 'experience', 'hedged', NULL, '{"accumulation_weeks":"7-8","rir_step_weeks":2}'::jsonb),
  ('periodization', 'markers', 'Author argues load and rep progression are roughly interchangeable for hitting target RIR across 5-30 reps, contrary to a bias inherited from strength sports that weight gains are superior.', 'mechanistic', 'moderate', NULL, '{"rep_range":"5-30"}'::jsonb),
  ('periodization', 'markers', 'Load progression becomes mandatory once working sets fall near or below ~30% 1RM (i.e., very high-rep sets), since adding more reps there stops adding stimulus and reps must be capped by a rep-range ceiling.', 'mechanistic', 'moderate', NULL, '{"threshold_pct_1rm":30}'::jsonb),
  ('periodization', 'markers', 'Rep progression causes disproportionately large relative-volume jumps at low rep counts -- e.g. adding one rep to a 6-rep set outweighs a typical small weight increase -- raising injury/fatigue risk if applied carelessly.', 'mechanistic', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'An algorithm scores post-session soreness and reps/RIR-vs-plan to set next-session volume: exceeding expectations adds 2-3 sets, on-target adds ~1 set, underperforming holds volume, and failing to match prior reps signals MRV breach requiring deload.', 'mechanistic', 'strong', NULL, '{"add_sets_overperform":"2-3","add_sets_ontarget":1}'::jsonb),
  ('periodization', 'deload', 'Deload/recovery is triggered adaptively (autoregulated) by failing to match prior session''s rep performance regardless of effort -- not by a fixed calendar -- treated as a direct maximum-recoverable-volume (MRV) breach signal.', 'mechanistic', 'moderate', NULL, NULL),
  ('periodization', 'transitions', 'A mesocycle should begin near minimum effective volume (MEV), established via a separate pump/effort/soreness scoring check, so early low-fatigue sessions leave room to add sets progressively before the final pre-deload week.', 'mechanistic', 'moderate', NULL, NULL),
  ('periodization', 'duration', 'In this NBA in-season context, a mesocycle equals one quarter of the 82-game season (~20 games, roughly 6-8 weeks); the season''s four quarters anchor periodic KPI testing.', 'experience', 'strong', NULL, '{"games_per_mesocycle":20,"weeks_per_mesocycle":"6-8","mesocycles_per_season":4}'::jsonb),
  ('periodization', 'duration', 'Microcycle length was deliberately lengthened from a 1-week block to a 14-day block to allow more agility in adjusting the plan while still anchoring short-term programming decisions.', 'experience', 'moderate', NULL, '{"microcycle_days":14}'::jsonb),
  ('periodization', 'models', 'Coach distinguishes top-down planning (macro-meso-micro sketched in advance) from bottom-up ''agile'' re-planning driven by actual response, arguing a rigid multi-month plan without agile adjustment is unrealistic over a long season.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'markers', 'Training organization is built around named biomotor qualities -- absolute strength, reactive strength, speed strength, and strength endurance -- each developed through a distinct movement-pattern ''menu,'' rather than through generic phase labels.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'In-season training days are grouped into three tiers -- high, moderate, low -- rather than named phases; full-team GPP vs SPP blocks remain an organizing layer beneath biomotor-quality planning.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'To retain already-built maximal strength through a season, coach cites unspecified applied research suggesting as little as 1-2 heavy sets weekly suffices -- a maintenance dose far below a building dose.', 'experience', 'hedged', NULL, '{"maintenance_sets_per_week":"1-2"}'::jsonb),
  ('periodization', 'transitions', 'Training dose is individualized by playing-time bucket: high-minute rotation players get volume/intensity turned toward pure maintenance, while low-minute players receive more development-focused training within the same team rhythm.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'transitions', 'Off-season re-entry stays general and low-commitment for the first 1-2 weeks before a more specific top-down block plan begins; formal baseline testing is deliberately delayed until the athlete is acclimated.', 'experience', 'moderate', NULL, '{"acclimation_weeks":"1-2"}'::jsonb),
  ('periodization', 'taxonomy', 'Classic periodization aims to peak performance at a set time; since hypertrophy is a continuous structural adaptation with no performance peak, that framework doesn''t meaningfully apply to muscle-growth programming.', 'mechanistic', 'strong', NULL, NULL),
  ('periodization', 'taxonomy', 'What looks like periodization in hypertrophy training is usually reactive ''training management'' -- unplanned mesocycle-to-mesocycle tweaks based on individual response, not a pre-planned long-term phase strategy.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'deload', 'Example mesocycle given: 4 weeks total, opening with a deload week then three progressively overloading weeks -- deload placed at the start rather than the more common end-of-block placement.', 'experience', 'moderate', NULL, '{"mesocycle_weeks":4,"deload_weeks":1,"overload_weeks":3,"deload_position":"start"}'::jsonb),
  ('periodization', 'transitions', 'Typical between-mesocycle adjustments cited are volume changes to lagging muscles and single exercise swaps (e.g. leg press to hack squat), not transitions between named phase types.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'models', 'Narrowly-defined periodization -- a dedicated block targeting a quality like work capacity before returning to hypertrophy training -- has little direct supporting evidence and should be used only for a clear identified bottleneck.', 'experience', 'hedged', NULL, NULL),
  ('periodization', 'duration', 'When a bottleneck-targeted block is used, it runs roughly 6 to 18 weeks; once the underlying quality improves, training reverts to concurrent hypertrophy work rather than continuing a phase sequence.', 'experience', 'hedged', NULL, '{"weeks_min":6,"weeks_max":18}'::jsonb),
  ('periodization', 'taxonomy', '''Periodization broadly'' -- deloading for physical/psychological refreshment, cycling specialization between muscle groups, and varying exercises for adherence -- is common practice but distinct from and far more common than dedicated-block periodization.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'models', 'Elaborate multi-phase periodization models aimed at maximizing hypertrophy are theoretically interesting but rarely address an actual common bottleneck, so most lifters should keep changes modest relative to an already-effective baseline.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'taxonomy', 'Conjugate training rotates three methods concurrently every week -- max effort, dynamic effort, and repeated effort/accessory -- rather than dedicating separate sequential blocks to each quality.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'markers', 'Max effort work is 1-3 reps at near-maximal effort on the main lift; dynamic effort is roughly 50%+ of 1RM lifted explosively; repeated effort/accessory is 2-4 exercises at 8-12 reps.', 'experience', 'strong', NULL, '{"me_reps_min":1,"me_reps_max":3,"de_pct_1rm_min":50,"re_exercises_min":2,"re_exercises_max":4,"re_reps_min":8,"re_reps_max":12}'::jsonb),
  ('periodization', 'transitions', 'The main max-effort exercise variation is rotated weekly to avoid accommodation, while accessory exercises rotate roughly every 3-4 weeks or when progress stalls; rotating too often is flagged as a common beginner error.', 'experience', 'strong', NULL, '{"main_lift_rotation_weeks":1,"accessory_rotation_weeks_min":3,"accessory_rotation_weeks_max":4}'::jsonb),
  ('periodization', 'duration', 'Expected progress benchmark is a 5-10% PR on the max-effort lift roughly every 8 weeks, with smaller, consistent weekly progressions expected on accessory work.', 'experience', 'moderate', NULL, '{"me_pr_pct_min":5,"me_pr_pct_max":10,"weeks":8}'::jsonb),
  ('periodization', 'models', 'Conjugate is positioned for lifters who already know the main lifts and want strength/power/speed; it is not recommended as the primary system when the main goal is muscle growth or general fitness.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'Standard prescription is 4 training days per week with 48-72 hours of recovery before retraining the same muscle groups or qualities again.', 'experience', 'strong', NULL, '{"days_per_week":4,"recovery_hours_min":48,"recovery_hours_max":72}'::jsonb),
  ('periodization', 'taxonomy', 'Tapering is loosely but consistently defined across sources by three elements: reduced training volume, maintained-or-increased intensity, and a predetermined time point relative to competition.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'deload', 'Dose-response research puts the effective taper volume cut, across all training sources, at roughly 41-60% of pre-taper volume; too little or too much both blunt the performance benefit.', 'cited_study', 'strong', NULL, '{"volume_reduction_pct_min":41,"volume_reduction_pct_max":60}'::jsonb),
  ('periodization', 'duration', 'Taper duration has no consensus: benefit appears from as little as 5 days up to 5 weeks; roughly 2 weeks suits moderately trained athletes, 3+ weeks suits highly trained strength/power athletes.', 'experience', 'moderate', NULL, '{"days_min":5,"weeks_max":5,"weeks_typical_moderate":2,"weeks_typical_advanced":3}'::jsonb),
  ('periodization', 'deload', 'Athletes with under about 2 years of training get an equivalent benefit from a single roughly one-week deload instead of a full multi-week taper, since they generate less fatigue to dissipate.', 'experience', 'moderate', NULL, '{"deload_weeks":1,"training_age_years_max":2}'::jsonb),
  ('periodization', 'markers', 'Intensity should be held steady or increased through most of the taper to slow detraining, then cut about 15-20% in only the final one to two sessions to clear residual micro-trauma.', 'mechanistic', 'strong', NULL, '{"final_intensity_cut_pct_min":15,"final_intensity_cut_pct_max":20,"final_sessions":2}'::jsonb),
  ('periodization', 'markers', 'During taper, less-trained athletes can cut session frequency 30-50%, but highly trained athletes (10+ years) should hold frequency constant and cut only per-session volume to preserve technical skill.', 'experience', 'moderate', NULL, '{"frequency_reduction_pct_min":30,"frequency_reduction_pct_max":50,"training_age_years":10}'::jsonb),
  ('periodization', 'models', 'Three taper shapes -- linear, exponential/step-down, and stepwise -- are all effective, but the exponential shape (fast initial drop, then leveling off) tends to perform best.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'deload', 'Full tapering should be reserved for genuinely important competitions and used at most 2-3 times per year, since the volume cut needed to peak costs meaningful long-term training time.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'Primary lifts are prescribed lower rep ranges (4-6, 6-8, or 8-10) than accessory lifts (8-10, 10-12, or up to 12-14) within the same hypertrophy block.', 'experience', 'moderate', NULL, '{"primary_rep_ranges":["4-6","6-8","8-10"],"accessory_rep_ranges":["8-10","10-12","12-14"]}'::jsonb),
  ('periodization', 'duration', 'A hypertrophy block is built as 4 weeks of rising training volume followed by a 5th deload week before starting the next block.', 'experience', 'moderate', NULL, '{"block_weeks":5,"deload_week":5}'::jsonb),
  ('periodization', 'markers', 'Progression within a block raises set count at a fixed rep target across weeks (e.g. 3x4, 3x6, 4x4, 4x6) rather than changing the rep range.', 'mechanistic', 'moderate', NULL, '{"progression_sets":["3","3","4","4"]}'::jsonb),
  ('periodization', 'deload', 'Deload week cuts training to roughly half the working sets used earlier in the block (e.g. 2 sets vs 3-4), at the block''s lower rep target.', 'experience', 'moderate', NULL, '{"deload_set_cut_pct":50}'::jsonb),
  ('periodization', 'models', 'Even within a hypertrophy-only block, rep range is mildly undulated across the week between two training days of the same lift, kept small so recovery isn''t compromised.', 'mechanistic', 'hedged', NULL, NULL),
  ('periodization', 'transitions', 'Only one exercise per muscle group is used per block; exercises are deliberately held in reserve so later blocks still offer a genuinely new stimulus rather than repeating variety immediately.', 'mechanistic', 'moderate', NULL, NULL),
  ('periodization', 'models', 'A DUP block ran three qualities per week (hypertrophy ~8 reps, strength 3-6 reps, power singles at submax load) across squat 4x, bench 3x, deadlift 2x weekly.', 'experience', 'moderate', NULL, '{"squat_freq_wk":4,"bench_freq_wk":3,"deadlift_freq_wk":2}'::jsonb),
  ('periodization', 'markers', 'Deadlift was trained only with singles, never rep sets, because it''s an all-concentric lift where setup dominates performance and touch-and-go reps don''t transfer to a true max attempt.', 'mechanistic', 'moderate', NULL, NULL),
  ('periodization', 'duration', 'The cycle was a 3-week overreaching volume phase followed by a 1-week taper (two days at 70% for triples, one day at 85% for a double), then 2 rest days before testing.', 'experience', 'moderate', NULL, '{"volume_phase_weeks":3,"taper_weeks":1,"taper_pct":[70,85,70],"rest_days_before_test":2}'::jsonb),
  ('periodization', 'deload', 'The overreaching phase caused severe early fatigue and soreness that resolved by the block''s end, matching a planned overreach-then-taper structure intended to yield supercompensation.', 'experience', 'hedged', NULL, NULL),
  ('periodization', 'models', 'They define periodization''s core mechanism as a weekly ''primary day'' deliberately set up for peak/heaviest performance, with other sessions intentionally under-dosed even when more could be tolerated.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'transitions', 'In hypertrophy-focused blocks they cut competition-lift frequency even while raising volume and proximity to failure, e.g. bench dropping from 4x/week in a strength block to 2-3x/week.', 'experience', 'moderate', NULL, '{"bench_freq_strength_block":4,"bench_freq_hypertrophy_block":"2-3"}'::jsonb),
  ('periodization', 'transitions', 'At a phase boundary, heavy competition-specific variants are swapped for more general or lower-fatigue variants (e.g. belt squat replacing back squat) while a primary heavy day is kept.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'The success metric changes by phase: hypertrophy/offseason blocks are judged by a composite performance score across several exercises or tolerated volume, strength blocks by top-end lift performance alone.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'taxonomy', 'They explicitly reject chasing one ''optimal frequency'' number per phase, preferring a principle-based needs-analysis approach that sets expectations and lets frequency/volume shift phase to phase.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'models', 'How far training deviates from immediate peak performance for long-term goals widens as training age (and possibly bodyweight/weight class) increases; novices can pursue most qualities at once.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'taxonomy', 'Periodization is defined as systematic variation of training variables like volume and intensity over time; a non-periodized program keeps the same sets/reps unchanged for the whole prep.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'duration', 'Traditional linear periodization runs distinct ~4-6 week mesocycles moving hypertrophy (10-15 reps) to strength (roughly 1-5 reps) to power, with volume declining and intensity rising each mesocycle.', 'experience', 'moderate', NULL, '{"mesocycle_weeks":"4-6","hypertrophy_reps":"10-15","strength_reps":"1-5"}'::jsonb),
  ('periodization', 'models', 'Linear periodization is described as superior to non-periodized training for strength and hypertrophy in trained/advanced lifters, but its variation is infrequent (once per mesocycle), motivating undulating models.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'taxonomy', 'Daily undulating periodization varies volume/intensity every session via two approaches: ''undulating the phases'' (a distinct hypertrophy/strength/power day each) or ''undulating the reps'' (day-to-day rep targets shift, e.g. 15/10/5) without naming phases.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'models', 'A cited study found a modified DUP order (hypertrophy, power, strength; 96h gap before strength) produced more volume and strength than the traditional order (hypertrophy, strength, power; 48h gap).', 'cited_study', 'strong', NULL, '{"modified_gap_hours":96,"traditional_gap_hours":48}'::jsonb),
  ('periodization', 'transitions', 'DUP and block periodization can be combined: a volume-block rep pattern (e.g. 10/8/6) is used further from competition, shifting to an intensity-block pattern (e.g. 6/4/2) in the final weeks.', 'experience', 'moderate', NULL, '{"volume_block_pattern":"10-8-6","intensity_block_pattern":"6-4-2"}'::jsonb),
  ('periodization', 'markers', 'Cited APRE progression uses an AMRAP top set against a rep target to set next week''s load jump: roughly +15lb for 9-10 reps over target, +10lb for 7-8, +5lb for 5-6, unchanged at target.', 'cited_study', 'strong', NULL, '{"reps_over_target_9_10":"+15lb","reps_over_target_7_8":"+10lb","reps_over_target_5_6":"+5lb"}'::jsonb),
  ('periodization', 'deload', 'Block length itself can be autoregulated: if a lifter still exceeds rep targets near the planned final week, the block is extended; if fatigue is excessive early, it''s cut short into a taper.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'taxonomy', 'Speaker distinguishes his planned ''undulating periodization'' from true daily undulating periodization (DUP), since his wave pattern is set weeks in advance rather than adjusted via daily autoregulated feedback.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'duration', 'Advanced ''low-medium-high'' wave model runs as a 4-week mesocycle: three ascending-difficulty weeks per lift followed by one deload week.', 'experience', 'strong', NULL, '{"weeks_build":3,"weeks_deload":1,"mesocycle_weeks":4}'::jsonb),
  ('periodization', 'duration', 'Intermediate ''alternating'' model runs a longer mesocycle: four weeks of alternating hard/light sessions across lifts before a deload week.', 'experience', 'strong', NULL, '{"weeks_build":4,"weeks_deload":1,"mesocycle_weeks":5}'::jsonb),
  ('periodization', 'markers', 'Within the alternating model, each lift''s second weekly session is programmed roughly 75% as difficult as that week''s first session, with every following week''s first session made harder than the prior week''s.', 'experience', 'moderate', NULL, '{"second_session_relative_pct":75}'::jsonb),
  ('periodization', 'deload', 'Deloads are placed on a fixed calendar position at the end of a 3- or 4-week build block rather than being triggered by autoregulated readiness signals.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'models', 'Model choice is athlete-dependent: lighter/shorter and advanced female lifters, who generate less fatigue per lift, suit the alternating wave; strong high-total or fatigue-prone athletes suit the low-medium-high wave.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'models', 'Uncontrolled daily-max-effort (''Bulgarian-style'') training is held up as violating planned undulation: without a scripted wave, a veteran of 13 years reportedly could never predict good vs. bad training days, undermining competition peaking.', 'experience', 'moderate', NULL, '{"years_experience_cited":13}'::jsonb),
  ('periodization', 'transitions', 'Accessory/secondary deadlift work changes selection by phase: an early general phase substitutes non-competition movements (RDL or vert pole) for technique, while other phases use light straight-bar deadlift sets instead.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'taxonomy', 'Peaking block is defined functionally, not just labeled: its explicit goal is minimizing fatigue while maximizing retained fitness for one specific day, achieved via narrowed specificity and neural sharpening rather than general adaptation.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'markers', 'Peaking-block overload sessions use 85%+ 1RM for 1-3 reps at 5-10 total overloading sets per lift weekly, contrasted with a general-strength phase''s 70-85% for 3-6 reps.', 'experience', 'strong', NULL, '{"peak_intensity_pct_1rm_min":85,"peak_reps":"1-3","peak_sets_per_lift_per_week":"5-10","strength_phase_intensity_pct_1rm":"70-85","strength_phase_reps":"3-6"}'::jsonb),
  ('periodization', 'markers', 'Final pre-meet ''priming week'' uses very low volume, fixed-percentage triples of singles per lift (e.g., squat 60-70%, bench 70-80%, deadlift 50-60% on the harder day), reduced a further 10-15% on the second priming day.', 'experience', 'strong', NULL, '{"squat_pct":"60-70","bench_pct":"70-80","deadlift_pct":"50-60","second_day_reduction_pct":"10-15"}'::jsonb),
  ('periodization', 'transitions', 'At the peaking-block boundary, exercise selection narrows to only competition-legal barbell squat/bench/deadlift, dropping accommodating-resistance and specialty-bar variations used in earlier general-prep phases.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'duration', 'Peaking-block length scales with lifter size, strength, and experience: about 3 weeks for beginners up to 3 months for elite lifters; taper length is categorized 1, 2, or 3 weeks by class.', 'experience', 'strong', NULL, '{"peaking_block_weeks_range":"3-13","taper_cat1_weeks":1,"taper_cat2_weeks":2,"taper_cat3_weeks":3}'::jsonb),
  ('periodization', 'deload', 'Taper''s final reduction phase scales by category: about 0-3 days (beginners) to 6-10 days (advanced); a standard deload week cuts intensity and volume to roughly 50-70% of the prior week.', 'experience', 'strong', NULL, '{"cat1_days":"0-3","cat2_days":"4-5","cat3_days":"6-10","deload_intensity_pct":"50-70","deload_volume_pct":"50-70"}'::jsonb),
  ('periodization', 'deload', 'A common athlete error near a meet is misjudging deload volume: switching to higher-rep ''light'' sets can produce more total tonnage than the low-volume max-effort session it replaced, adding fatigue instead of shedding it.', 'experience', 'strong', NULL, NULL),
  ('periodization', 'transitions', 'Speaker''s own 9-week peaking macrocycle subdivides by rep-max specificity: an initial 4-week block (3 hard + 1 deload) trains heavy doubles, a second identical-structure block trains heavy singles, before a 14-day final taper.', 'experience', 'strong', NULL, '{"total_weeks":9,"block1_weeks":4,"block2_weeks":4,"final_taper_days":14}'::jsonb),
  ('periodization', 'transitions', 'Moving from contest prep into off-season, one coach keeps exercise selection and program structure essentially unchanged from the final prep program, increasing only training volume as food intake and recovery capacity rise.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'markers', 'During contest-prep dieting, training volume cannot keep rising as the caloric deficit deepens; falling energy availability caps work capacity, limiting how much volume late prep can support versus the off-season.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'models', 'One coach downplays meticulous periodization planning, arguing that adherence and consistent training over time (''compound interest'') drives results more than precisely scripted progression, as long as some progress exists.', 'experience', 'moderate', NULL, NULL),
  ('periodization', 'taxonomy', 'Coach floats an optional short overreaching phase, possibly with body-part specialization, at the very start of off-season before reverting to standard higher-volume structure, framed as an occasional choice, not default.', 'experience', 'hedged', NULL, NULL);
